        array = newArray;
    }
    if(byteArrayValue == null){
        java.util.Arrays.fill(array, size, size + byteLength, (byte)0);
    } else {
        System.arraycopy(byteArrayValue, byteOffset, array, size, byteLength);
    }
    size = newSize;
    return this;
}

