final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    final byte[] buffer = this.classFileBuffer;
    // constant pool starts after magic(4) + minor(2) + major(2) + constant_pool_count(2) = 10
    int offset = 10;
    int currentIndex = 1;
    while (currentIndex < constantPoolEntryIndex) {
        if (offset >= buffer.length) {
            throw new IllegalArgumentException("Reached end of buffer before finding entry");
        }
        int tag = buffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: { // CONSTANT_Utf8
                if (offset + 1 >= buffer.length) {
                    throw new IllegalArgumentException("Malformed constant pool entry");
                }
                int len = ((buffer[offset] & 0xFF) << 8) | (buffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            }
            case 3: case 4: { // Integer, Float
                offset += 4;
                break;
            }
            case 5: case 6: { // Long, Double (take two entries)
                offset += 8;
                currentIndex++; // skip the second entry
                break;
            }
            case 7: case 8: case 16: { // Class, String, MethodType
                offset += 2;
                break;
            }
            case 9: case 10: case 11: case 12: case 18: { // Fieldref, Methodref, InterfaceMethodref, NameAndType, InvokeDynamic
                offset += 4;
                break;
            }
            case 15: { // MethodHandle
                offset += 3;
                break;
            }
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
        currentIndex++;
    }
    // Now offset points to the target entry
    if (offset >= buffer.length) {
        throw new IllegalArgumentException("Reached end of buffer before reading target entry");
    }
    int tag = buffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    offset++;
    if (offset + 1 >= buffer.length) {
        throw new IllegalArgumentException("Malformed CONSTANT_Utf8 entry");
    }
    int length = ((buffer[offset] & 0xFF) << 8) | (buffer[offset + 1] & 0xFF);
    offset += 2;
    if (offset + length > buffer.length) {
        throw new IllegalArgumentException("CONSTANT_Utf8 entry exceeds buffer length");
    }
    // Decode UTF-8 bytes into charBuffer
    java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(buffer, offset, length);
    java.nio.CharBuffer charBuf = java.nio.CharBuffer.wrap(charBuffer);
    java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
    decoder.decode(byteBuf, charBuf, true);
