protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Ensure the target type is Character or char
    if (type != null && type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char, but was: " + type);
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return cs.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert CharSequence to Character: length != 1");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new IllegalArgumentException("Number value out of char range: " + intVal);
        }
        return (char) intVal;
    }
    if (value instanceof Boolean) {
        throw new IllegalArgumentException("Cannot convert Boolean to Character");
    }
    // Fallback: try toString and take first character if length is 1
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }
    throw new IllegalArgumentException("Cannot convert value to Character: " + value);
}

