private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source list is the same as this list or empty, nothing to do
    if (list == this || list.size == 0) {
        return;
    }

    // Attach the source list to the end of this list
    if (this.size == 0) {
        // This list is empty, simply adopt the source list's nodes
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Link the two lists together
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update the size of this list
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

