private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    if (predicate.test(start) || start.equals(stop)) {
        return circ;
    }
    Node current = start;
    while (true) {
        if (dir > 0) {
            circ.next();
        } else {
            circ.prev();
        }
        current = circ.getNode();
        if (current.equals(stop) || predicate.test(current)) {
            return circ;
        }
        if (current.equals(start)) {
            // looped back to start without finding a match; return the circulator at stop
            return circ;
        }
    }
}

