protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour == null || tour.isEmpty()){
        return null;
    }
    // Build adjacency map: vertex -> list of incident edges
    java.util.Map<V, java.util.List<E>> adjacency = new java.util.HashMap<>();
    for(E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(e);
    }
    // Pick a starting vertex from the first edge
    E firstEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(firstEdge);
    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    vertexList.add(startVertex);
    V current = startVertex;
    E prevEdge = null;
    while(true){
        java.util.List<E> edges = adjacency.get(current);
        if(edges == null || edges.isEmpty()){
            break;
        }
        E nextEdge = null;
        for(E e : edges){
            if(prevEdge != null && e.equals(prevEdge)){
                continue;
            }
            nextEdge = e;
            break;
        }
        if(nextEdge == null){
            break;
        }
        edgeList.add(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current) ?
                       graph.getEdgeTarget(nextEdge) :
                       graph.getEdgeSource(nextEdge);
        vertexList.add(nextVertex);
        // Remove the used edge from adjacency lists
        adjacency.get(current).remove(nextEdge);
        adjacency.get(nextVertex).remove(nextEdge);
        prevEdge = nextEdge;
        current = nextVertex;
        if(current.equals(startVertex)){
            java.util.List<E> remaining = adjacency.get(current);
            if(remaining == null || remaining.isEmpty()){
                break;
            }
        }
    }
    double weight = 0.0;
    for(E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.traverse.DefaultGraphPath<>(graph, startVertex, current, vertexList, edgeList, weight);
}

