private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        Integer maxLower = null;
        for (K other : keys) {
            if (((Comparable<? super K>) other).compareTo(key) < 0) {
                Integer val = (Integer) other;
                if (maxLower == null || val > maxLower) {
                    maxLower = val;
                }
            }
        }
        lowerBounds.add(maxLower != null ? maxLower : -1);
    }
    return lowerBounds;
}

