                            sb.append((char) value);
                            i += 5;
                        } else {
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                case 'U':
                    // unicode escape: 8 hex digits
                    if (i + 10 <= len) {
                        String hexStr = input.substring(i + 2, i + 10);
                        if (isHexDigitString(hexStr)) {
                            long value = Long.parseLong(hexStr, 16);
                            sb.append(Character.toChars((int) value));
                            i += 9;
                        } else {
                            sb.append('\\').append('U');
                            i++;
