private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b0 = bb.get(i) & 0xFF;
    int numBytes = 1;
    int codePoint;

    if ((b0 & 0x80) == 0) {
        // 1-byte sequence
        codePoint = b0;
    } else if ((b0 & 0xE0) == 0xC0) {
        // 2-byte sequence
        numBytes = 2;
        if (i + 1 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b1 = bb.get(i + 1) & 0xFF;
        if ((b1 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        if (codePoint < 0x80) { // overlong
            sb.append('\uFFFD');
            return i + 2;
        }
    } else if ((b0 & 0xF0) == 0xE0) {
        // 3-byte sequence
        numBytes = 3;
        if (i + 2 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        if (codePoint < 0x800) { // overlong
            sb.append('\uFFFD');
            return i + 3;
        }
    } else if ((b0 & 0xF8) == 0xF0) {
        // 4-byte sequence
        numBytes = 4;
        if (i + 3 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        int b3 = bb.get(i + 3) & 0xFF;
        if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        if (codePoint < 0x10000 || codePoint > 0x10FFFF) { // overlong or out of range
            sb.append('\uFFFD');
            return i + 4;
        }
    } else {
        // Invalid first byte
        sb.append('\uFFFD');
        return i + 1;
    }

    // Append decoded character(s)
    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
