public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Count preceding backslashes
        int backslashCount = 0;
        int j = i - 1;
        while (j >= 0 && str.charAt(j) == '\\') {
            backslashCount++;
            j--;
        }
        // If backslashCount is odd, this backslash is escaped (literal)
        if ((backslashCount & 1) == 1) {
            sb.append('\\');
            continue;
        }
        // This backslash starts an escape sequence
        if (i + 1 >= len) {
            // Trailing backslash, treat as literal
            sb.append('\\');
            continue;
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                // Unicode escape: \uXXXX
                if (i + 5 >= len) {
                    throw new Exception("Invalid unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid unicode escape sequence '\\u" + hex + "' at position " + i);
                }
                i += 5; // skip 'u' and four hex digits
                break;
            default:
                // Unknown escape, keep as is
                sb.append(next);
                i++;
                break;
        }
    }
    return sb.toString();
}

