public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    boolean leadingSlash = path.startsWith("/");
    Deque<String> stack = new ArrayDeque<>();

    // Process the base path
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else {
            stack.push(part);
        }
    }

    // Process the relative path
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else {
            stack.push(part);
        }
    }

    // Build the resulting path
    List<String> resultParts = new ArrayList<>(stack);
    Collections.reverse(resultParts); // stack was LIFO
    String result = String.join("/", resultParts);
    if (leadingSlash) {
        result = "/" + result;
    }
    // Handle the case where the result is empty
    if (result.isEmpty() && leadingSlash) {
        return "/";
    }
    return result;
}

