public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    // If no time ranges specified, return all snapshots
    boolean filterByTime = timeRanges != null && !timeRanges.isEmpty();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Expected format: timestamp,threadId,stackTrace
            // Split into at most 3 parts to preserve commas in stackTrace
            String[] parts = line.split(",", 3);
            if (parts.length < 3) {
                continue; // malformed line
            }
            long timestamp;
            try {
                timestamp = Long.parseLong(parts[0].trim());
            } catch (NumberFormatException e) {
                continue; // invalid timestamp
            }
            String threadId = parts[1].trim();
            String stackTrace = parts[2].trim();
            if (filterByTime) {
                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start = range.getStartTime();
                    long end = range.getEndTime();
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
                    }
                }
                if (!inRange) {
                    continue; // skip snapshot outside all ranges
                }
            }
            // Create ThreadSnapshot instance (assumes a suitable constructor exists)
            result.add(new ThreadSnapshot(timestamp, threadId, stackTrace));
        }
    }
    return result;
}

