public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int n = desiredCapacity;
    if (n % 2 == 0) {
        n++; // make it odd
    }
    while (true) {
        boolean prime = true;
        if (n <= 1) {
            prime = false;
        } else if (n <= 3) {
            prime = true;
        } else if (n % 2 == 0 || n % 3 == 0) {
            prime = false;
        } else {
            for (int i = 5; (long) i * i <= n; i += 6) {
                if (n % i == 0 || n % (i + 2) == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) {
            return n;
        }
        n += 2; // skip even numbers
    }
}

